div.script:
(function () {

  const COOKIE_NAME = 'user_cookie_preferences';
  const COOKIE_EXPIRATION_DAYS = 365;

  const CATEGORY_KEYS = ['marketing', 'personalization', 'analytics'];

  const COOKIE_MAP = {
    marketing: ['_fbp', '_gcl_au'],
    personalization: ['user_theme'],
    analytics: ['_ga', '_gid']
  };

  // Elements
  const banner = document.getElementById('modal2');
  const prefsModal = document.querySelector('[consent-element="manage"]');

  const savePrefsBtn = document.querySelector('[data-save-settings]');

  const marketingCheckbox = document.getElementById('Marketing');
  const personalizationCheckbox = document.getElementById('Personalization');
  const analyticsCheckbox = document.getElementById('Analytics');
  const existingPrefs = getCookie(COOKIE_NAME);
  // Cookie helpers
  function setCookie(name, value, days) {
    const expires = `expires=${new Date(Date.now() + days * 864e5).toUTCString()}`;
    document.cookie = `${name}=${JSON.stringify(value)};${expires};path=/;SameSite=Lax`;
  }

  function getCookie(name) {
    const cookies = `; ${document.cookie}`.split(`; ${name}=`);
    return cookies.length === 2 ? JSON.parse(cookies.pop().split(';')[0]) : null;
  }

  function eraseCookie(name) {
    document.cookie = `${name}=; Max-Age=0; path=/;`;
  }

  function deleteCookiesForCategory(category) {
    (COOKIE_MAP[category] || []).forEach(eraseCookie);
  }

  function handleCategoryCookies(prefs) {
    CATEGORY_KEYS.forEach(category => {
      if (!prefs[category]) deleteCookiesForCategory(category);
    });
  }

  function savePreferences(prefs) {
    setCookie(COOKIE_NAME, prefs, COOKIE_EXPIRATION_DAYS);
    handleCategoryCookies(prefs);
  }

  // UI helpers
  function hideConsentUI() {
    if (banner){
    		banner.classList.add('hide');
        banner.classList.remove('show');
    }
    if (prefsModal){
    	prefsModal.classList.add('hide');
      prefsModal.classList.remove('show');
    }
  }

  function showConsentModal() {
    if (prefsModal){
    	prefsModal.classList.add('show');
      prefsModal.classList.remove('hide');
    }
    if (banner){
    	banner.classList.remove('show')
      banner.classList.add('hide')
    }
  }

  function updateCheckboxes(prefs) {

    if (marketingCheckbox) {
      marketingCheckbox.checked = prefs.marketing === true;
    }

    if (personalizationCheckbox) {
      personalizationCheckbox.checked = prefs.personalization === true;
    }

    if (analyticsCheckbox) {
      analyticsCheckbox.checked = prefs.analytics === true;
    }

  }

  function handleConsentClick(allow) {

    const prefs = {
      marketing: allow,
      personalization: allow,
      analytics: allow
    };

    updateCheckboxes(prefs);
    savePreferences(prefs);
    hideConsentUI();

  }

  // ACCEPT ALL
  document.querySelectorAll('[data-accept-all]').forEach(el =>
    el.addEventListener('click', e => {
      e.preventDefault();
      handleConsentClick(true);
    })
  );

  // REJECT ALL
  document.querySelectorAll('[data-reject-all]').forEach(el =>
    el.addEventListener('click', e => {
      e.preventDefault();
      handleConsentClick(false);
    })
  );

  // OPEN PREFERENCES
  function attachOpenPrefsHandler() {

    const openBtns = document.querySelectorAll('[data-manage-settings], [data-consent-element="open-preferences"]');

    openBtns.forEach(btn => {

      btn.addEventListener('click', e => {

        e.preventDefault();

        const storedPrefs = getCookie(COOKIE_NAME) || {
          marketing: false,
          personalization: false,
          analytics: false
        };

        updateCheckboxes(storedPrefs);

        showConsentModal();

      });

    });

  }

  attachOpenPrefsHandler();

  // SAVE SETTINGS
  if (savePrefsBtn) {

    savePrefsBtn.addEventListener('click', e => {

      e.preventDefault();

      const prefs = {
        marketing: marketingCheckbox ? marketingCheckbox.checked : false,
        personalization: personalizationCheckbox ? personalizationCheckbox.checked : false,
        analytics: analyticsCheckbox ? analyticsCheckbox.checked : false
      };

      savePreferences(prefs);
      hideConsentUI();
    });

  }

  // Close buttons
  const closeBanner = document.getElementById('close-modal-x21');
  const closeModal = document.querySelector('.close-consent');

  if (closeBanner) {
    closeBanner.addEventListener('click', () => {
      if (banner){
      banner.classList.remove('show');
      banner.classList.add('hide');
      }
    });
  }

  if (closeModal) {
    closeModal.addEventListener('click', () => {
      if (prefsModal){
      prefsModal.classList.remove('show');
      prefsModal.classList.add('hide');
      }
    });
  }

  if (existingPrefs) {
    if (banner){
    banner.classList.remove('show');
    banner.classList.add('hide');
    }
  }
})();

body.script:
document.addEventListener("DOMContentLoaded", function() {
  const header = document.querySelector('.nav.v2.scrolling');
  const tabs = document.querySelector('.section.py-0.background-transparent.demo-tabs');

  document.querySelectorAll('a[href^="#"]').forEach(link => {
    link.addEventListener('click', function(e) {
      const targetId = this.getAttribute('href');
      if (!targetId || targetId === '#') return;

      const target = document.querySelector(targetId);
      if (!target) return;

      e.preventDefault();

      // Get current heights (after layout settles)
      const headerH = header ? header.offsetHeight : 0;
      const tabsH = tabs ? tabs.offsetHeight : 0;
      const offset = headerH + tabsH + 10;

      const targetTop = target.getBoundingClientRect().top + window.scrollY - offset;

      // Let layout settle, then scroll
      setTimeout(() => {
        window.scrollTo({
          top: targetTop,
          behavior: 'smooth'
        });
      }, 50);
    });
  });
});  
  // Scroll behavior for navigation - Fixed version to prevent shaking
  let lastScrollTop = 0;
  const nav = document.querySelector(".nav.v2");
  let ticking = false;

  function updateNav() {
    const scrollTop =
          window.pageYOffset || document.documentElement.scrollTop;

    if (scrollTop > 0) {
      nav.classList.add("scrolling");
    } else {
      nav.classList.remove("scrolling");
    }

    ticking = false;
  }

  window.addEventListener("scroll", function () {
    if (!ticking) {
      requestAnimationFrame(updateNav);
      ticking = true;
    }
  });

 function googleTranslateElementInit() {
      new google.translate.TranslateElement({pageLanguage: 'en', layout: google.translate.TranslateElement.FloatPosition.TOP_LEFT}, 'google_translate_element');
    }

  function triggerHtmlEvent(element, eventName) {
    var event;
    if (document.createEvent) {
    event = document.createEvent('HTMLEvents');
    event.initEvent(eventName, true, true);
    element.dispatchEvent(event);
    } else {
    event = document.createEventObject();
    event.eventType = eventName;
    element.fireEvent('on' + event.eventType, event);
    }
  }

  jQuery('.lang-select').click(function() {
    var theLang = jQuery(this).attr('data-lang');
    jQuery('.goog-te-combo').val(theLang);

    //alert(jQuery(this).attr('href'));
    window.location = jQuery(this).attr('href');
    location.reload();

  });

