$(document).ready(function() {
  const d = new Date();
  const y = d.getFullYear();
  $("#footer-year").text(y);
  $('#search').keyup(function() {
    const text = $(this).val();
    if (text.length > 2) {
      setTimeout(()=> {
		$.ajax({
        url: window.location.origin + "/search?query=" + text,
        type: 'GET',
        success: function(res) {
          $('#search-result').show();
          var success = $($.parseHTML(res)).find("#search-result-items");
          if (success.length == 0) {
            $('#search-result').html('
Sorry, no results found. Please try with different keywords.');
          } else {
            $('#search-result').html(success);
          }
        }
      });
	}, 500);
    } else {
      $("#search-result").hide();
      $('#search-result').empty();
    }
  });
  $('.search-overlay').click(function(e) {
    e.stopPropagation();
    console.log("Overlay")
    $('.search-overlay').hide();
    $('#search').val('');
    $('#search-result').hide().empty();
  });
  $('.search-wrap').click(function(e) {
    e.stopPropagation();
    console.log("Form")
  });
});

